solution.greet.sh:
#!/usr/bin/env bash
usage() { echo "usage: greet.sh [-u] [-c COUNT] [-n NAME]" >&2; exit 2; }
name=world
count=1
upper=0
while getopts ':n:c:u' o; do
  case $o in
    n) name=$OPTARG ;;
    c) count=$OPTARG ;;
    u) upper=1 ;;
    *) usage ;;
  esac
done
shift $((OPTIND - 1))
[ $# -eq 0 ] || usage
case $count in ''|*[!0-9]*|0) usage ;; esac
line="Hello, $name!"
if [ "$upper" = 1 ]; then line=$(printf '%s' "$line" | tr 'a-z' 'A-Z'); fi
for ((i = 0; i < count; i++)); do printf '%s\n' "$line"; done

