#!/usr/bin/env bash
usage() { echo "usage: convert.sh -f UNIT -t UNIT VALUE..." >&2; exit 2; }
from= to=
while getopts ':f:t:' o; do
  case $o in
    f) from=$OPTARG ;;
    t) to=$OPTARG ;;
    *) usage ;;
  esac
done
shift $((OPTIND - 1))
factor() {
  case $1 in
    m) echo 1 ;; km) echo 1000 ;; mi) echo 1609.344 ;; ft) echo 0.3048 ;; in) echo 0.0254 ;;
    *) return 1 ;;
  esac
}
a=$(factor "$from") || usage
b=$(factor "$to") || usage
[ $# -gt 0 ] || usage
for v in "$@"; do
  if ! [[ $v =~ ^-?[0-9]+(\.[0-9]+)?$ ]]; then
    echo "bad value: $v" >&2
    exit 2
  fi
  awk -v v="$v" -v a="$a" -v b="$b" 'BEGIN { printf "%.3f\n", v * a / b }'
done

