            problems.append(f"{tag}: exit status {r['rc']}, expected {e['rc']}" + (f" (stderr: {r['stderr'].strip().splitlines()[-1][:160]})" if r["stderr"].strip() else ""))
        mode = cfg.get("stdout", "exact")
        if mode != "ignore":
