        if re.search(pat, code):
            print(f"FAIL: {spec['script']} must not rely on {pat!r} (it has to run with plain `{spec.get('shell', 'sh')}`)")
            sys.exit(1)
    bad = 0
    for scn in spec["scenarios"]:
