def snapshot(box, mtimes, dirs, nlink=False, sorted_paths=()):
    out = {}
    for d, dirnames, files in os.walk(box):
        dirnames.sort()
        rel = os.path.relpath(d, box)
        for dn in list(dirnames):
            p = os.path.join(d, dn)
            r = os.path.normpath(os.path.join(rel, dn))
